    H,W=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=[[False]*W for _ in range(H)]
    from collections import deque
    for i in range(H):
        for j in range(W):
            if grid[i][j] and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
