                            seen[ny][nx]=True; q.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                t_,l_,b_,r_=min(ys),min(xs),max(ys),max(xs)
                rings={}
                for y,x in comp:
                    k=min(y-t_,b_-y,x-l_,r_-x)
                    rings.setdefault(k,set()).add(grid[y][x])
                ks=sorted(rings)
                assert all(len(rings[k])==1 for k in ks), (ks,[rings[k] for k in ks])
                cols=[next(iter(rings[k])) for k in ks]
                n=len(cols)-1
                for y,x in comp:
                    k=min(y-t_,b_-y,x-l_,r_-x)
                    out[y][x]=cols[n-k]
    return out

